def test_windows_explicit_normal_priority(monkeypatch):
    import subprocess
    import click
    import click._termui_impl as impl

    monkeypatch.setattr(impl, 'WIN', True)
    monkeypatch.setattr(subprocess, 'NORMAL_PRIORITY_CLASS', 0x20, raising=False)
    calls = []

    class Process:
        def wait(self):
            return 0

    def popen(*args, **kwargs):
        calls.append(kwargs)
        return Process()

    monkeypatch.setattr(subprocess, 'Popen', popen)
    click.edit(filename='example.txt', editor='editor', process_priority='normal')
    assert len(calls) == 1
    assert calls[0].get('creationflags', 0) & subprocess.NORMAL_PRIORITY_CLASS, (
        'Explicit normal priority must use NORMAL_PRIORITY_CLASS, not inherit '
        'a potentially lowered parent priority.'
    )

def test_completion_resources_remain_open_during_callback():
    from contextlib import contextmanager
    import click
    from click.shell_completion import ShellComplete

    @contextmanager
    def resource():
        state = {"closed": False}
        try:
            yield state
        finally:
            state["closed"] = True

    def setup(ctx, param, value):
        if value:
            ctx.obj = ctx.with_resource(resource())

    def complete(ctx, param, incomplete):
        return ["closed" if ctx.obj["closed"] else "open"]

    @click.command()
    @click.option("--setup", is_flag=True, callback=setup, expose_value=False)
    @click.argument("value", shell_complete=complete)
    def cli(value):
        pass

    completion = ShellComplete(cli, {}, "cli", "_CLI_COMPLETE")
    results = completion.get_completions(["--setup"], "")
    assert [item.value for item in results] == ["open"]

def test_completion_does_not_mutate_parent_context():
    import click
    from click.shell_completion import ShellComplete

    parent = click.Context(click.Command('parent'), obj={'nested': {'data': []}})
    parent.meta['key'] = {'nested': []}

    def complete(ctx, incomplete):
        ctx.obj['nested']['data'].append('leaked')
        ctx.meta['key']['nested'].append('leaked')
        return []

    command = click.Command('child', shell_complete=complete)
    completion = ShellComplete(command, {'parent': parent}, 'child', '_CHILD_COMPLETE')
    assert completion.get_completions([], '') == []
    assert parent.obj == {'nested': {'data': []}}
    assert parent.meta == {'key': {'nested': []}}

