def test_conflicts_rejected_before_option_processing():
    import click
    from click.testing import CliRunner

    processed = []

    def process_option(ctx, param, value):
        processed.append(param.name)
        return value

    @click.command()
    @click.option('--json', is_flag=True, conflicts_with=['xml'], callback=process_option)
    @click.option('--xml', is_flag=True)
    def cli(json, xml):
        processed.append('command')

    result = CliRunner().invoke(cli, ['--json', '--xml'])
    assert result.exit_code == 2
    assert "Option '--json' cannot be used together with '--xml'." in result.output
    assert processed == [], 'Application option callbacks ran before conflict rejection'

