def test_history_tracks_option_changes_during_execution():
    import click
    from click.testing import CliRunner

    observed = {}

    @click.command(track_changes=True)
    @click.option('--count', type=int, default=1)
    @click.pass_context
    def cmd(ctx, count):
        ctx.params['count'] = 9
        observed['history'] = ctx.get_option_history('--count')

    result = CliRunner().invoke(cmd, ['--count', '5'])
    assert result.exit_code == 0, repr(result.exception)
    assert [entry['value'] for entry in observed['history']] == [5, 9]

def test_invoked_command_records_default_option_history():
    import click
    from click.core import ParameterSource

    @click.command(track_changes=True)
    @click.option('--count', type=int, default=7)
    def child(count):
        assert count == 7
        return click.get_current_context().get_option_history('--count')

    with click.Context(click.Command('caller')) as ctx:
        history = ctx.invoke(child)

    assert history, 'The invoked command used a default but recorded no history'
    assert history[0]['value'] == 7
    assert history[0]['source'] is ParameterSource.DEFAULT
    assert isinstance(history[0]['timestamp'], (int, float))

def test_default_source_survives_invoke_and_forward():
    import click
    from click.core import ParameterSource
    from click.testing import CliRunner

    histories = []

    @click.command(track_changes=True)
    @click.option('--count', type=int, default=7)
    @click.pass_context
    def destination(ctx, count):
        histories.append(ctx.get_option_history('--count'))

    @click.command(track_changes=True)
    @click.option('--count', type=int, default=7)
    @click.pass_context
    def intermediate(ctx, count):
        ctx.forward(destination)

    @click.command()
    @click.pass_context
    def entry(ctx):
        ctx.invoke(intermediate)

    result = CliRunner().invoke(entry, [])
    assert result.exit_code == 0, repr(result.exception)
    assert histories and histories[0]
    assert histories[0][0]['value'] == 7
    assert histories[0][0]['source'] is ParameterSource.DEFAULT

