def test_delegating_loader_does_not_chain_aliases():
    import pytest
    from jinja2 import DictLoader, Environment, TemplateNotFound

    class DelegatingLoader(DictLoader):
        def get_source(self, environment, template):
            return super().get_source(environment, template)

    loader = DelegatingLoader({'final.html': 'unexpected chained result'})
    loader.add_alias('old.html', 'middle.html')
    loader.add_alias('middle.html', 'final.html')
    env = Environment(loader=loader)
    with pytest.raises(TemplateNotFound) as exc:
        env.get_template('old.html')
    assert exc.value.name == 'middle.html'

def test_transform_exception_without_writable_attributes_propagates():
    import pytest
    from jinja2 import ChoiceLoader, DictLoader, Environment, TemplateNotFound

    class ReadOnlyTemplateNotFound(TemplateNotFound):
        def __init__(self, name):
            super().__init__(name)
            self._sealed = True

        def __setattr__(self, name, value):
            if getattr(self, '_sealed', False):
                raise AttributeError('exception is read-only')
            super().__setattr__(name, value)

    error = ReadOnlyTemplateNotFound('transform failed')

    def transform(name):
        raise error

    env = Environment(loader=ChoiceLoader([
        DictLoader({}, path_transform=transform),
        DictLoader({'home': 'fallback'}),
    ]))
    with pytest.raises(ReadOnlyTemplateNotFound) as caught:
        env.get_template('home')
    assert caught.value is error

