def test_start_callback_runs_in_background(monkeypatch, tmp_path):
    import threading
    import subprocess
    import click

    class Process:
        pid = 12345

        def poll(self):
            return 0

        def wait(self):
            return 0

    monkeypatch.setattr(subprocess, "Popen", lambda *a, **kw: Process())
    caller = threading.get_ident()
    callback_threads = {}

    def callback(event_type, process_id, editor_command, timestamp):
        callback_threads[event_type] = threading.get_ident()

    filename = tmp_path / "draft.txt"
    filename.write_text("draft")
    click.edit(filename=str(filename), editor="editor", monitor_process=callback)

    assert "start" in callback_threads
    assert callback_threads["start"] != caller, "start callback must run independently in the monitoring thread"

def test_empty_editor_return_matches_public_annotation(monkeypatch):
    import inspect
    import typing
    import click
    from click._termui_impl import Editor

    monkeypatch.setattr(Editor, 'edit_file', lambda self, filename: None)
    result = click.edit(require_save=False)
    assert result == ''

    return_types = []
    for overload in typing.get_overloads(click.edit) or [click.edit]:
        try:
            inspect.signature(overload).bind(require_save=False)
        except TypeError:
            continue
        hints = typing.get_type_hints(overload)
        if isinstance(None, hints['text']):
            return_types.append(hints['return'])

    assert any(isinstance(result, annotation) for annotation in return_types), (
        'No applicable public signature permits the actual string return value'
    )

def test_windows_editor_preserves_quoted_option_values(monkeypatch):
    import subprocess
    from click import _termui_impl

    monkeypatch.setattr(_termui_impl, "WIN", True)
    captured = {}

    class Process:
        def wait(self):
            return 0

    def popen(command, **kwargs):
        captured['command'] = command
        captured.update(kwargs)
        return Process()

    monkeypatch.setattr(subprocess, 'Popen', popen)
    editor = _termui_impl.Editor(
        editor='"C:\\Program Files\\Editor\\editor.exe" --user-data-dir="C:\\work files"',
        editor_args=['--wait'],
    )
    editor.edit_file('notes.txt')

    assert captured['command'] == [
        'C:\\Program Files\\Editor\\editor.exe',
        '--user-data-dir=C:\\work files',
        '--wait',
        'notes.txt',
    ]

def test_unsupported_preexec_priority_falls_back(monkeypatch, tmp_path):
    import subprocess
    import click
    import click._termui_impl as impl

    monkeypatch.setattr(impl, 'WIN', False)
    calls = []

    class Process:
        def wait(self):
            return 0

    def popen(args, **kwargs):
        calls.append(kwargs)
        if 'preexec_fn' in kwargs:
            raise RuntimeError('preexec_fn not supported within subinterpreters')
        return Process()

    monkeypatch.setattr(subprocess, 'Popen', popen)
    filename = tmp_path / 'edit.txt'
    filename.write_text('text')
    click.edit(filename=str(filename), editor='editor', process_priority='low')
    assert len(calls) == 2
    assert 'preexec_fn' not in calls[1]

def test_completion_can_use_context_resource():
    from io import StringIO
    import click
    from click.shell_completion import BashComplete, CompletionItem

    class ResourceCommand(click.Command):
        def parse_args(self, ctx, args):
            ctx.obj = ctx.with_resource(StringIO('available'))
            return super().parse_args(ctx, args)

        def shell_complete(self, ctx, incomplete):
            return [CompletionItem(ctx.obj.read())]

    command = ResourceCommand('cli')
    completion = BashComplete(command, {}, 'cli', '_CLI_COMPLETE')
    results = completion.get_completions([], '')
    assert [item.value for item in results] == ['available']

