def test_chain_completion_closes_every_context():
    import click
    from click.shell_completion import ShellComplete

    closed = []
    parsed = []

    def register_cleanup(ctx, param, value):
        name = ctx.info_name
        parsed.append(name)
        ctx.call_on_close(lambda: closed.append(name))
        return value

    @click.group(chain=True)
    def cli():
        pass

    @cli.command()
    @click.option('--value', default='x', callback=register_cleanup)
    def first(value):
        pass

    @cli.command()
    @click.option('--value', default='x', callback=register_cleanup)
    def second(value):
        pass

    completion = ShellComplete(cli, {}, 'cli', '_CLI_COMPLETE')
    completion.get_completions(['first', 'second'], '')
    assert parsed == ['first', 'second']
    assert sorted(closed) == ['first', 'second']

def test_completion_does_not_mutate_parent_state():
    import click
    from click.shell_completion import ShellComplete

    parent = click.Context(click.Command('root'), obj={'nested': {'data': 'original'}})
    parent.meta['key'] = {'nested': 'original'}

    def complete(ctx, incomplete):
        ctx.obj['nested']['data'] = 'changed'
        ctx.meta['key']['nested'] = 'changed'
        return []

    command = click.Command('child', shell_complete=complete)
    completion = ShellComplete(command, {'parent': parent}, 'child', '_CHILD_COMPLETE')
    assert completion.get_completions([], '') == []
    assert parent.obj == {'nested': {'data': 'original'}}
    assert parent.meta == {'key': {'nested': 'original'}}

