def test_required_if_accepts_value_consumed_by_callback():
    import click
    from click.testing import CliRunner

    for requirement in ({"required": True}, {"required_if": {"auth": "basic"}}):
        consumed = []
        invoked = []

        def consume_password(ctx, param, value):
            consumed.append(value)
            return None

        @click.command()
        @click.option("--auth")
        @click.option("--password", expose_value=False, callback=consume_password, **requirement)
        def cli(auth):
            invoked.append(auth)

        result = CliRunner().invoke(cli, ["--auth", "basic", "--password", "secret"])
        assert consumed == ["secret"]
        assert result.exit_code == 0, result.output
        assert invoked == ["basic"]

