def test_priority_preserves_variable_names():
    from jinja2 import Environment

    for newstyle in (False, True):
        env = Environment(extensions=['jinja2.ext.i18n'])
        env.install_null_translations(newstyle=newstyle)
        ordinary = env.from_string(
            "{% trans _jinja2_kw_user='Ada' %}Hello {{ _jinja2_kw_user }}{% endtrans %}"
        )
        prioritized = env.from_string(
            "{% trans priority=0, _jinja2_kw_user='Ada' %}Hello {{ _jinja2_kw_user }}{% endtrans %}"
        )
        assert ordinary.render() == 'Hello Ada'
        assert prioritized.render() == 'Hello Ada'

def test_context_dependent_translation_remains_correct():
    from jinja2 import Environment, pass_context

    @pass_context
    def gettext(context, message):
        return context['language'] + ':' + message

    env = Environment(extensions=['jinja2.ext.i18n'])
    env.install_gettext_callables(gettext, lambda s, p, n: s if n == 1 else p, newstyle=True)
    template = env.from_string('{{ gettext("hello") }}')
    assert template.render(language='en') == 'en:hello'
    assert template.render(language='fr') == 'fr:hello'

def test_translation_respects_evaluation_context():
    from jinja2 import Environment, pass_eval_context

    @pass_eval_context
    def gettext(eval_ctx, message):
        return 'escaped' if eval_ctx.autoescape else 'plain'

    env = Environment(extensions=['jinja2.ext.i18n'], autoescape=False)
    env.install_gettext_callables(gettext, lambda s, p, n: s if n == 1 else p)
    template = env.from_string('{{ gettext("hello") }}|{% autoescape true %}{{ gettext("hello") }}{% endautoescape %}')
    assert template.render() == 'plain|escaped'

def test_context_aware_translation_preserves_template_name():
    from jinja2 import DictLoader, Environment, pass_context

    env = Environment(
        loader=DictLoader({
            'first': '{% trans %}Hello{% endtrans %}',
            'second': '{% trans %}Hello{% endtrans %}',
        }),
        extensions=['jinja2.ext.i18n'],
    )

    @pass_context
    def gettext(context, message):
        return context.name + ':' + message

    env.install_gettext_callables(
        gettext, lambda singular, plural, n: singular if n == 1 else plural,
        newstyle=False,
    )
    assert env.get_template('first').render() == 'first:Hello'
    assert env.get_template('second').render() == 'second:Hello'

def test_independent_nested_lookup_resolves_alias():
    from jinja2 import Environment, FunctionLoader

    def get_source(name):
        if name == 'outer':
            return env.get_template('inner_alias').render()
        if name == 'inner':
