def test_retryable_generator_manager_subclass():
    import click
    from contextlib import _GeneratorContextManager

    attempts = []
    cleaned = []

    def resource():
        yield
        cleaned.append(True)

    class RetryableManager(_GeneratorContextManager):
        def __exit__(self, *args):
            attempts.append(1)
            if len(attempts) == 1:
                raise RuntimeError('transient failure before cleanup')
            return super().__exit__(*args)

    ctx = click.Context(click.Command('cmd'), retry_cleanup=1)
    ctx.with_resource(RetryableManager(resource, (), {}))
    ctx.close()
    assert len(attempts) == 2
    assert cleaned == [True]

