def test_windows_editor_argument_preserves_literal_percent(monkeypatch):
    import os
    import re
    import subprocess
    from click import _termui_impl

    variable = 'CLICK_EDITOR_LITERAL'
    replacement = 'unexpected_expanded_editor_argument'
    monkeypatch.setenv(variable, replacement)
    monkeypatch.setattr(_termui_impl, 'WIN', True)

    class Process:
        def wait(self):
            return 0

    def popen(command, env=None, shell=False, **kwargs):
        if shell:
            # Model cmd.exe's percent-variable expansion, which also occurs
            # within double-quoted executable arguments.
            environment = os.environ if env is None else env
            expanded = re.sub(
                r'%([^%]+)%',
                lambda match: environment.get(match.group(1), match.group(0)),
                command,
            )
            assert replacement not in expanded, (
                'Literal editor argument was expanded by cmd.exe: ' + expanded
            )
        return Process()

    monkeypatch.setattr(subprocess, 'Popen', popen)
    _termui_impl.Editor(
        editor='example-editor', editor_args=['%' + variable + '%']
    ).edit_file('document.txt')

