def test_completion_resources_remain_open_during_callback():
    import click
    from click.shell_completion import CompletionItem, ShellComplete

    class ResourceCommand(click.Command):
        def make_context(self, *args, **kwargs):
            ctx = super().make_context(*args, **kwargs)
            ctx.obj = {"closed": False}
            ctx.call_on_close(lambda: ctx.obj.update(closed=True))
            return ctx

    def complete(ctx, incomplete):
        assert not ctx.obj["closed"], "context closed before completion callback"
        return [CompletionItem("available")]

    cli = ResourceCommand("cli", shell_complete=complete)
