def test_completion_can_use_context_resource():
    import click
    from contextlib import contextmanager
    from click.shell_completion import BashComplete, CompletionItem

    @contextmanager
    def resource():
        state = {"closed": False}
        try:
            yield state
        finally:
            state["closed"] = True

    class ResourceContext(click.Context):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.obj = self.with_resource(resource())

    class ResourceCommand(click.Command):
        context_class = ResourceContext

        def shell_complete(self, ctx, incomplete):
            return [CompletionItem("closed" if ctx.obj["closed"] else "open")]

    completion = BashComplete(ResourceCommand("cli"), {}, "cli", "_CLI_COMPLETE")
    assert [item.value for item in completion.get_completions([], "")] == ["open"]

