def test_overloads_accept_text_with_filename():
    import inspect
    import typing
    import click

    # This supported call must have a matching overload, not merely an
    # implementation signature: filename takes precedence over text.
    overloads = typing.get_overloads(click.edit)
    assert overloads
    for overload in overloads:
        try:
            inspect.signature(overload).bind('initial text', filename='file.txt')
        except TypeError:
            continue
        text_type = typing.get_type_hints(overload)['text']
        if text_type is not type(None):
            break
    else:
        raise AssertionError('No overload accepts non-None text together with filename')

