def test_completion_can_use_context_resource():
    from contextlib import contextmanager
    from click import Command
    from click.shell_completion import CompletionItem, ShellComplete

    @contextmanager
    def resource():
        state = {'closed': False}
        try:
            yield state
        finally:
            state['closed'] = True

    class ResourceCommand(Command):
        def parse_args(self, ctx, args):
            ctx.obj = ctx.with_resource(resource())
            return super().parse_args(ctx, args)

        def shell_complete(self, ctx, incomplete):
            assert not ctx.obj['closed'], 'resource closed before completion'
            return [CompletionItem('result')]

    cli = ResourceCommand('demo')
    completion = ShellComplete(cli, {}, 'demo', '_DEMO_COMPLETE')
    assert [item.value for item in completion.get_completions([], '')] == ['result']

