def test_snapshot_does_not_silently_lose_nested_isolation():
    import threading
    import click

    ctx = click.Context(click.Command('cli'), obj={
        'resource': threading.Lock(),
        'nested': {'data': ['original']},
    })
    try:
        snapshot = ctx.save_state()
    except TypeError:
        # Explicitly rejecting an uncopyable resource is preferable to
        # returning a snapshot that cannot provide its isolation guarantee.
        return

    ctx.obj['nested']['data'].append('temporary')
    ctx.restore_state(snapshot)
    assert ctx.obj['nested']['data'] == ['original']

