def test_text_overload_allows_unsaved_return(monkeypatch):
    import inspect
    import types
    import typing
    import click

    def accepts(annotation, value):
        if annotation is typing.Any:
            return True
        if isinstance(annotation, typing.TypeVar):
            constraints = annotation.__constraints__
            return not constraints or any(accepts(item, value) for item in constraints)
        if typing.get_origin(annotation) in (typing.Union, types.UnionType):
            return any(accepts(item, value) for item in typing.get_args(annotation))
        return isinstance(value, annotation)

    class Process:
        def wait(self):
            return 0

    monkeypatch.setattr('subprocess.Popen', lambda *args, **kwargs: Process())
    arguments = {'text': 'draft', 'editor': 'fake-editor'}
    result = click.edit(**arguments)
    assert result is None

    applicable = []
    for overload in typing.get_overloads(click.edit):
        hints = typing.get_type_hints(overload)
        try:
            bound = inspect.signature(overload).bind(**arguments)
        except TypeError:
            continue
        if all(accepts(hints[name], value) for name, value in bound.arguments.items()):
            applicable.append(hints['return'])
    assert applicable, 'No overload accepts this previously supported call'
    assert accepts(applicable[0], result), 'The selected overload excludes the actual unsaved return value'

