        return cli

    runner = CliRunner()
    args = ['--mode', 'basic', '--password', 'secret']
    ordinary = runner.invoke(make_command({'required': True}), args)
    assert ordinary.exit_code == 0, ordinary.output
    conditional = runner.invoke(make_command({'required_if': {'mode': 'basic'}}), args)
    assert conditional.exit_code == 0, conditional.output
    assert conditional.output == ordinary.output

def test_dynamic_source_is_resolved_before_its_dependent():
