def test_explicit_boolean_flag_overrides_dynamic_default():
    import click
    from click.testing import CliRunner

    @click.command()
    @click.option('--mode', default='off')
    @click.option('--enabled', is_flag=True, default={'--mode': {'off': False}})
    def cli(mode, enabled):
        click.echo(repr(enabled))

    runner = CliRunner()
    result = runner.invoke(cli, [])
    assert result.exit_code == 0, result.output
    assert result.output.strip() == 'False'
