    assert result.exit_code == 0, result.output
    assert result.output.strip() == 'True'

def test_conflicts_are_rejected_before_option_callbacks():
    import click
    from click.testing import CliRunner

    processed = []

    def process_option(ctx, param, value):
        processed.append(param.name)
        return value

    @click.command()
    @click.option('--first', is_flag=True, conflicts_with=['second'], callback=process_option)
    @click.option('--second', is_flag=True, callback=process_option)
    def command(first, second):
        processed.append('command')

    result = CliRunner().invoke(command, ['--first', '--second'], standalone_mode=False)
    assert isinstance(result.exception, click.UsageError)
    assert processed == []

def test_prompt_conflict_precedes_callbacks():
    import click
    from click.testing import CliRunner

    seen = []

    def record(ctx, param, value):
        seen.append(value)
        return value

    @click.command()
    @click.option('--quiet', is_flag=True, conflicts_with=['name'])
    @click.option('--name', prompt=True, callback=record)
    def cli(quiet, name):
        seen.append('command')

    result = CliRunner().invoke(cli, ['--quiet'], input='Alice\n')
    assert result.exit_code == 2, result.output
    assert "cannot be used together" in result.output
    assert seen == [], 'Application callback ran before prompt conflict rejection'

def test_conflict_declaration_preserves_option_parse_override():
    import click
    from click.testing import CliRunner

    seen = []

    class RecordingOption(click.Option):
        def handle_parse_result(self, ctx, opts, args):
            seen.append(self.name)
            return super().handle_parse_result(ctx, opts, args)

    @click.command()
    @click.option('--left', is_flag=True, cls=RecordingOption,
                  conflicts_with=['right'])
    @click.option('--right', is_flag=True)
    def cli(left, right):
        pass

    result = CliRunner().invoke(cli, ['--left'])
    assert result.exit_code == 0, result.output
    assert seen == ['left'], 'Option parse override was bypassed'

def test_help_does_not_trigger_prompt_conflicts():
    import click
