    @click.command()
    @click.option('--first', prompt=True, conflicts_with=['second'])
    @click.option('--second', prompt=True)
    def command(first, second):
        raise AssertionError('command must not run for help')

    result = CliRunner().invoke(command, ['--help'])
    assert result.exit_code == 0, result.output
    assert 'Show this message and exit.' in result.output
    assert 'cannot be used together' not in result.output

def test_explicit_false_reaches_custom_command_constructor():
    import click
    from click.testing import CliRunner

    class TrackingCommand(click.Command):
        def __init__(self, *args, track_changes=True, **kwargs):
            super().__init__(*args, track_changes=track_changes, **kwargs)

    observed = []

    @click.command(cls=TrackingCommand, track_changes=False)
    @click.option('--count', default=1)
    def command(count):
        observed.append(click.get_current_context().get_option_history('count'))

    result = CliRunner().invoke(command)
    assert result.exit_code == 0, result.output
    assert observed == [None]

def test_params_update_records_value_changes():
    import click

    @click.command(track_changes=True)
    @click.option('--count', type=int, default=1)
    def cmd(count):
        pass

    with cmd.make_context('cmd', []) as ctx:
        ctx.params.update(count=2)
        assert ctx.params['count'] == 2
        assert [entry['value'] for entry in ctx.get_option_history('count')] == [1, 2]

def test_unexposed_option_still_has_history():
    import click
    from click.core import ParameterSource

    @click.command(track_changes=True)
    @click.option('--count', type=int, expose_value=False)
    def cmd():
        pass

    with cmd.make_context('cmd', ['--count', '5']) as ctx:
        history = ctx.get_option_history('--count')
        assert history
        assert history[-1]['value'] == 5
        assert history[-1]['source'] is ParameterSource.COMMANDLINE

def test_priority_preserves_substitution_variable_names():
    from jinja2 import Environment

    for newstyle in (False, True):
        env = Environment(extensions=['jinja2.ext.i18n'])
        env.install_null_translations(newstyle=newstyle)
        for name in ('message', 'context'):
            source = '{% trans priority=1, ' + name + '="Ada" %}Hello {{ ' + name + ' }}{% endtrans %}'
            assert env.from_string(source).render() == 'Hello Ada'
        for name in ('singular', 'plural', 'context'):
            source = '{% trans priority=1, n=2, ' + name + '="Ada" %}{{ ' + name + ' }} item{% pluralize %}{{ ' + name + ' }} items{% endtrans %}'
            assert env.from_string(source).render() == 'Ada items'

def test_context_aware_translation_remains_context_sensitive():
    from jinja2 import Environment, pass_context

    @pass_context
    def translate(context, message):
        return context['language'] + ':' + message

    env = Environment(extensions=['jinja2.ext.i18n'])
    env.install_gettext_callables(translate, lambda s, p, n: s if n == 1 else p, newstyle=True)
    template = env.from_string("{{ gettext('hello') }}")
    assert template.render(language='en') == 'en:hello'
    assert template.render(language='fr') == 'fr:hello'

def test_translation_respects_custom_sandbox_callable_policy():
    import pytest
    from jinja2.sandbox import SandboxedEnvironment
    from jinja2.exceptions import SecurityError

    def translate(message):
        return message

    class RestrictedEnvironment(SandboxedEnvironment):
        def is_safe_callable(self, obj):
            return obj is not translate and super().is_safe_callable(obj)

    env = RestrictedEnvironment(extensions=['jinja2.ext.i18n'])
    env.install_gettext_callables(
        translate, lambda singular, plural, n: singular if n == 1 else plural,
        newstyle=False,
    )
    with pytest.raises(SecurityError):
        env.from_string("{{ gettext('hello') }}").render()

def test_delegating_get_source_override_does_not_chain_aliases():
    from jinja2 import DictLoader, Environment

    class DelegatingLoader(DictLoader):
        def get_source(self, environment, template):
            return super().get_source(environment, template)

    loader = DelegatingLoader({'middle.html': 'middle', 'final.html': 'final'})
    loader.add_alias('old.html', 'middle.html')
    loader.add_alias('middle.html', 'final.html')
    env = Environment(loader=loader)
    assert env.get_template('old.html').render() == 'middle'

def test_existing_custom_listing_arguments_remain_supported():
    from jinja2 import BaseLoader

    class ExistingLoader(BaseLoader):
        def list_templates(self, suffix='', *, reverse=False):
            return sorted(
                (name for name in ['a.html', 'b.txt'] if name.endswith(suffix)),
                reverse=reverse,
            )

    loader = ExistingLoader()
    assert loader.list_templates('.html') == ['a.html']
    assert loader.list_templates(suffix='', reverse=True) == ['b.txt', 'a.html']

def test_staticmethod_listing_remains_compatible():
    from jinja2 import BaseLoader

    class StaticLoader(BaseLoader):
        @staticmethod
        def list_templates():
            return ['public.html', 'private.txt']

    loader = StaticLoader()
    assert loader.list_templates() == ['public.html', 'private.txt']
    loader.add_filter('*.txt')
    assert loader.list_templates() == ['public.html']


def test_classmethod_listing_remains_compatible():
    from jinja2 import BaseLoader

    class ClassLoader(BaseLoader):
        templates = ['public.html', 'private.txt']

        @classmethod
        def list_templates(cls):
            return list(cls.templates)

    loader = ClassLoader()
    assert loader.list_templates() == ['public.html', 'private.txt']
    loader.add_filter('*.txt')
    assert loader.list_templates() == ['public.html']
